css:
html {
    font-size: 140% !important;
    background-color: #f6efe2 !important;
    -webkit-text-size-adjust: none;
}
body {
    line-height: 2.20 !important;
    max-width: 42em !important;
    margin: 0 auto !important;
    padding: 2em 1.6em 6em !important;
    background-color: #f6efe2 !important;

}
body { color: #3a3226; }
img, svg, video { max-width: 100% !important; height: auto !important; }
table { max-width: 100% !important; display: block; overflow-x: auto; }
/* コードは等幅で読めることを最優先にし、内側の色付けには触れない */
pre, code, kbd, samp {
    font-family: "SF Mono", ui-monospace, Menlo, monospace !important;
    background-color: #ece3d2 !important;
}
pre {
    padding: 0.8em 1em !important;
    border-radius: 6px;
    overflow-x: auto !important;
    white-space: pre !important;
    word-break: normal !important;
}
